graphql.query:
query listSloOfferingByFamily($id: String!, $filters: [String!]) {
  listSloOfferingByFamily(id: $id) @filter(filters: $filters) {
    ...SimpleProductOfferingFragment
    childOffering {
      ...ProductOfferingChildRefFragment
      productOffering {
        ...SimpleProductOfferingFragment
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment SimpleProductOfferingFragment on ProductOffering {
  id
  orderNumber
  name
  description
  isTangible
  templateId
  isAppliedByBusinessRule
  extendedParameters
  effectiveLifecycleStatus
  productOfferingPrice {
    id
    ...ProductOfferingPriceRefFragment
    __typename
  }
  category {
    id
    name
    origin {
      offeringCountMax
      __typename
    }
    __typename
  }
  productFamily {
    id
    name
    __typename
  }
  channel {
    id
    name
    __typename
  }
  prodSpecCharValueUse {
    defaultValue {
      value
      isDefault
      __typename
    }
    businessType
    extendedParameters
    availableValue {
      value
      __typename
    }
    __typename
  }
  localizedData {
    description
    locale
    name
    __typename
  }
  enrichmentContainer {
    name
    validFor {
      startDateTime
      endDateTime
      __typename
    }
    staticEnrichment {
      name
      atType
      value
      localizedGroup {
        ...LocalizedDataParts
        __typename
      }
      localizedName {
        ...LocalizedDataParts
        __typename
      }
      localizedValue {
        ...LocalizedDataParts
        __typename
      }
      group
      __typename
    }
    entity {
      id
      __typename
    }
    wrapper {
      name
      enrichment {
        name
        component {
          name
          order
          attribute {
            name
            value
            meta
            __typename
          }
          __typename
        }
        attribute {
          name
          meta
          localizedValue {
            description
            locale
            name
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  validFor {
    startDateTime
    endDateTime
    __typename
  }
  __typename
}

fragment ProductOfferingPriceRefFragment on ProductOfferingPriceRef {
  id
  origin {
    eligibility {
      id
      __typename
    }
    validFor {
      startDateTime
      endDateTime
      __typename
    }
    ... on ProductOfferPriceCharge {
      id
      pricePlanId
      priceType
      saleType
      prodSpecCharValueUse {
        name
        businessType
        productSpecCharacteristicValue {
          name
          value
          __typename
        }
        __typename
      }
      price {
        value
        units
        __typename
      }
      isBasePrice
      isDefaultPrice
      installmentPlan {
        id
        name
        downPayment
        downPaymentMax
        downPaymentMin
        downPaymentType
        installmentPeriod
        installmentPeriodUnits
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

fragment LocalizedDataParts on LocalizedData {
  name
  description
  locale
  __typename
}

fragment ProductOfferingChildRefFragment on ProductOfferingToChildProductOfferingRef {
  id
  childMin
  childMax
  name
  orderNumber
  defaultBehavior
  cardinalityDefault
  __typename
}
